{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    id_to_node = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    retained = set(n['id'] for n in nodes)
    removed = []
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if not node['removable']:
            continue
        if node['parent'] is None:
            continue
        if node['symbol'] in required_symbols:
            continue
        if any(cid in retained for cid in children.get(nid, [])):
            continue
        temp_retained = retained - {nid}
        symbols_present = set()
        for rid in temp_retained:
            symbols_present.add(id_to_node[rid]['symbol'])
        if all(sym in symbols_present for sym in required_symbols):
            retained = temp_retained
            removed.append(nid)
    retained_ids = sorted(retained)
    return {"removed_node_ids": removed, "retained_node_ids": retained_ids}"
}
